fn swap_first_last(v: Vec<Int>) -> Vec<Int> {
    let len = len(&v) - 1
    let first = get(&v, 0)
    let last = get(&v, len)
    let mut result = vec()
    push(result, last)
    for i in 1 {
        if i != len {
            push(result, get(&v, i))
        }
    }
    push(result, first)
    result
}

