fn sort(v: Vec<Int>) -> Vec<Int> {
    let mut result = vec()
    for x in v {
        if result.is_empty() {
            result.push(x)
        } else {
            let mut i = 0
            while i < result.len() && result.get(i) > x {
                i = i + 1
            }
            result.insert(i, x)
        }
    }
    result
}

