fn to_int(c: Str) -> Int {
    c.parse_int().unwrap()
}

fn is_digit(c: Str) -> Bool {
    c >= "0" && c <= "9"
}

fn print(x: Int) -> Unit {
    println(x)
}

fn println(x: Int) -> Unit {
    print(x)
    print_str("\n")
}

fn print_str(s: Str) -> Unit {
    println(s)
}

fn unwrap(x: Option<Int>) -> Int {
    match x {
        Some(n) => n,
        None => panic("unwrap called on None"),
    }
}

fn panic(s: Str) -> Unit {
    eprintln(s)
    exit(1)
}

