struct Rectangle { width: Int, height: Int }

fn area(rect: Rectangle) -> Int {
    rect.width * rect.height
}

fn perimeter(rect: Rectangle) -> Int {
    2 * (rect.width + rect.height)
}

fn main() {
    let rect = Rectangle { width: 9, height: 3 }
    print(area(rect))
    print(perimeter(rect))
}

fn area(w: Int, h: Int) -> Int {
    w * h
}

fn perimeter(w: Int, h: Int) -> Int {
    2 * (w + h)
}

fn main() {
    let rect = (9.0.to_int() - trunc(0.5, 9.0.to_int()) - trunc(0.5, 3.0.to_int())) * (3.0.to_int() - trunc(0.5, 3.0.to_int()) - trunc(0.5, 3.0.to_int()))
    print(rect)
    drop rect
    let peri = 2 * (9.0.to_int() - trunc(0.5, 9.0.to_int()) - trunc(0.5, 3.0.to_int()) + 3.0.to_int() - trunc(0.5, 3.0.to_int()) - trunc(0.5, 3.0.to_int()))
    print(peri)
    drop peri
}

fn area(w: Int, h: Int) -> Int {
    w * h
}

fn perimeter(w: Int, h: Int) -> Int {
    2 * (w + h)
}

fn main() {
    let rect = area(9, 3)
    print(rect)
    drop rect
    let peri = perimeter(9, 3)
    print(peri)
